const raw = $json.body;
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid ATSH event payload');
const id = String(raw.id ?? '');
const type = raw.type;
const key = raw.key;
const payload = raw.payload;
if (!id || id.length > 128 || !/^[a-z]+(?:[._][a-z]+)+$/.test(type || '') || typeof key !== 'string' || !key || key.length > 180 || !payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('Invalid ATSH event envelope');
if ($json.headers?.['x-atsh-idempotency-key'] !== key || String($json.headers?.['x-atsh-event-id'] ?? '') !== id) throw new Error('ATSH event headers do not match payload');
return {json:{event_id:id,event_type:type,idempotency_key:key,payload}};
